/* ============================================================
   Legal modal viewer (QA: footer T&C / Privacy links should open
   a modal instead of leaving the checkout).
   Intercepts clicks on links to the legal pages and shows them in
   an in-page overlay.

   Content source (Offer Flow):
   - window.SWIFTLY_OFFER_FLOW.terms_conditions / .privacy_policy
     injected from offers.* (admin → Configure Offer Settings →
     Offer Common Data). Empty fields show a “not configured” message.
   - Static front preview without offer_id falls back to DOCS below
     (legacy copy from terms-and-conditions.html / privacy-policy.html).

   Links keep their real href, so no-JS and middle-click still work.
   ============================================================ */
(function () {
  "use strict";

  var LEGAL = /(terms-and-conditions|privacy-policy)\.html|\/checkout\/(tc|pp)\/?([?#]|$)|(^|[\/?#])(tc|pp)([?#]|$)/i;

  function isLegalHref(href) {
    var h = String(href || "");
    if (LEGAL.test(h)) return true;
    try {
      var u = new URL(h, window.location.href);
      var p = u.pathname.replace(/\/+$/, "");
      return /\/(terms-and-conditions|privacy-policy)\.html$/i.test(p)
        || /\/checkout\/(tc|pp)$/i.test(p)
        || /^\/(tc|pp)$/i.test(p);
    } catch (e) {
      return false;
    }
  }

  function legalKindFromHref(href) {
    var h = String(href || "");
    if (/privacy-policy|\/pp([?#]|$)|(^|[\/?])pp([?#]|$)/i.test(h)) return "privacy";
    return "terms";
  }

  /* Copy lifted from the standalone legal pages. Keep in sync if those change. */
  var DOCS = {
    terms: {
      title: "Terms & Conditions",
      html: "<main class=\"legal-main\">\n                    <p><span>This vacation package is valid for residents of the United States and Canada. The\n                            purchaser of this vacation is\n                            entitled to a Poconos area vacation for two adults and up to two children in the same\n                            room and includes three\n                            nights&rsquo; accommodation at Pocono Mountain Villas. In the event the accommodation is\n                            not available at our\n                            partner resort, you will be offered alternative hotel accommodation rated 3 stars or\n                            higher such as Ramada, Days\n                            Inn, Travelodge or similar. &nbsp;This offer includes a bonus of a 3 or 4-Night Cruise\n                            Vacation for two adults\n                            upon staying at the hotel and attending a required presentation described below in more\n                            detail. Travel must be\n                            completed within 12 months of the purchase date of the vacation. The promoter of this\n                            vacation is VacationVIP,\n                            LLC located at 5900 Lake Ellenor Drive Suite 300 Orlando, FL 32809. Vacation\n                            reservations are processed and\n                            conﬁrmed by our resort partners, Exploria Resorts. &nbsp;VacationGurus is a registered\n                            Seller of Travel Florida\n                            No.&nbsp;</span><span>ST 44476</span><span>. VacationGurus can be reached via 1-855-34\n                            GURUS (1-855-344-8787)\n                            (Mon-Fri 9:00 am &ndash; 5:00 pm ET). The verifiable retail value of this promotional\n                            vacation based on February\n                            2026 travel is up to $728 based on applicable hotel taxes and Resort fees per published\n                            rates and online travel\n                            agency rates published on the Internet for the applicable accommodations in the Poconos.\n                            The verifiable retail\n                            value of the bonus vacation certificate is up to $1575. The verifiable retail value of\n                            the entire vacation\n                            package is up to $2303 depending upon time of year. All Hotels require valid photo\n                            identiﬁcation and a valid\n                            major credit or debit card upon check-in to cover the cost of incidental charges such as\n                            meals, gratuities,\n                            hotel taxes, resort fees and parking which are not included and are itemized below\n                            (</span><span>pre-Paid debit\n                            cards are not accepted). &nbsp;</span><span>Hotel room taxes of approximately $12 to $32\n                            per night (depending on\n                            hotel, day of the week, and time of year) are payable directly to the hotel upon\n                            check-in at the hotel.\n                            &nbsp;Resort Fees and Parking of approximately $15 to $35 per day plus tax are payable\n                            directly to the hotel\n                            upon check-in. All fees charged and/or credit card preauthorization&rsquo;s by the hotel\n                            are subject to change\n                            at the hotel&rsquo;s discretion.&nbsp;</span></p>\n                    <p><br></p>\n                    <p><span>RESERVATIONS</span></p>\n                    <p><span>You may complete your reservation request form online or contact our Reservation\n                            partner, Exploria Resorts at\n                            1-877-201-6133 (Mon-Fri 9:00 am &ndash; 8:00 pm ET). Check-ins are available seven days\n                            per week on a\n                            space-available basis and are subject to VacationGurus hotel allotments. Please provide\n                            a minimum of 30\n                            days&rsquo; advance notice prior to your requested check-in date as certain days of the\n                            week and times of the\n                            year sell out quickly and become extremely limited. Certain times of the year (such as\n                            holidays, peak seasonal\n                            travel dates, large conventions, sporting events, and special events) may be available\n                            for an additional fee.\n                            Please contact Exploria&rsquo;s Reservations Department for more details at\n                            1-877-201-6133 (Mon-Fri 9:00 am\n                            &ndash; 8:00 pm ET). Do not book airline ﬂights or secure travel until you have received\n                            your Confirmed\n                            Itinerary letter from Exploria or alternative partner.&nbsp;</span></p>\n                    <p><br></p>\n                    <p><span>To secure your preferred travel dates and other options you must contact Exploria\n                            Resorts or alternative\n                            partner directly (dates selected at time of purchase are a request of desired check-in\n                            dates and are not secured\n                            at that time). Final confirmation of a reservation is required to avoid penalties from\n                            the resort or hotel\n                            partner. Reservations that are not confirmed may be cancelled and cannot be reinstated\n                            for the same dates.\n                            Please check your travel itinerary for the specific steps you need to follow to confirm\n                            your plans.</span></p>\n                    <p><br></p>\n                    <p><span>RESERVATIONS CHANGES</span></p>\n                    <p><span>Changes to a conﬁrmed reservation for this promotional offer are accepted up to 7 days\n                            prior to arrival for a\n                            $250 change fee unless you have purchased the Travel Protection in advance of changing\n                            your arrival dates. Any\n                            changes to a hotel reservation within 4 days of arrival, no Shows to the hotel or\n                            failure to attend the\n                            presentation in its entirety will result in forfeiture of the vacation package and all\n                            monies paid plus a charge\n                            of $500 to offset the retail rate of accommodations.</span></p>\n                    <p><br></p>\n                    <p><br></p>\n                    <p><span>ELIGIBILITY</span></p>\n                    <p><span>To be eligible to participate in this promotional offer, adult couples or singles must\n                            meet the following\n                            qualiﬁcations: be employed full-time with a minimum, annual gross household income of\n                            $60,000 or retired and if\n                            retired, must be 55 years of age or older. All participants must be creditworthy and\n                            carry an active major\n                            credit card or debit card (pre-paid debit cards are not acceptable). &nbsp;Participants\n                            must speak English\n                            ﬂuently. Additionally, if married or cohabiting, one traveler must be at least 28 years\n                            of age and are required\n                            to travel and attend the entire presentation together. Married and Cohabiting couples\n                            must have provide matching\n                            valid government issued identiﬁcation with the same address. Single women must be at\n                            least 30 years of age,\n                            provide a valid government issued identification and meet the qualiﬁcations listed\n                            above. Attendance at a sales\n                            presentation on the beneﬁts of a discounted Vacation Membership Program, lasting\n                            approximately 90 to 120\n                            minutes, (depending upon your level of interest) is required. Minimum credit\n                            qualiﬁcations must be met to stay\n                            at the advertised accommodations. Alternative accommodation may be offered for those\n                            that do not meet the\n                            minimum qualiﬁcations as outlined above and require a $150.00 Save The Date refundable\n                            deposit collected at the\n                            time of booking. This Pocono vacation is fully transferable to another party that meets\n                            the qualiﬁcations with\n                            payment of a $100.00 transfer fee.</span></p>\n                    <p><br></p>\n                    <p><span>This offer may not be combined or used in conjunction with any other offer provided by\n                            the promoter, or its\n                            aﬃliates. This offer is limited to one vacation per household/family within or outside\n                            of the same residence and\n                            is not valid for more than one couple traveling together, groups traveling together,\n                            family reunions, two or\n                            more families traveling together, or for anyone attending a convention or conference.\n                            Those who violate the\n                            previously mentioned group policy will only be eligible to attend one presentation\n                            together regardless of the\n                            number of vacation packages being used. Those who do not attend the presentation in its\n                            entirety will forfeit\n                            all monies collected and will be charged the retail value of the accommodation and\n                            amenities.</span></p>\n                    <p><br></p>\n                    <p><span>BONUS GIFT</span></p>\n                    <p><span>This promotional offer includes a bonus vacation certificate for a complementary 3- or\n                            4-night Caribbean\n                            Cruise. &nbsp;This certificate will be issued to the contact information provided at the\n                            time of sale via email\n                            &amp; text upon completion of your initial vacation &amp; attendance at the required sales\n                            presentation in its\n                            entirety. &nbsp;See Certiﬁcate for complete terms and conditions. Reservations are\n                            completed by GOCRV who can be\n                            reached by calling 954-525-1777, Monday &ndash; Friday 9:30am-5pm ET, once you have\n                            received and registered your\n                            cruise certificate. &nbsp;</span></p>\n                    <p><br></p>\n                    <p><span>PICK YOUR PARADISE</span></p>\n                    <p><span>This optional vacation includes 4-nights of hotel accommodation for 2 adults and up to\n                            2 children with your\n                            choice from 30 Domestic destinations &amp; 10 International destinations. &nbsp;This\n                            vacation is valid for use\n                            for 12 months. The Pick Your Paradise Vacation certificate will be issued to the contact\n                            information provided at\n                            the time of sale for your original promotional offer via email &amp; text. Reservations are\n                            completed by GOCRV\n                            who can be reached by calling 954-525-1777 once you have received and registered your\n                            vacation certificate.\n                            &nbsp;</span></p>\n                    <p><br></p>\n                    <p><span>ADDITIONAL TERMS</span></p>\n                    <p><br></p>\n                    <p><span>The following people are not eligible for this promotional offer: employees of any\n                            fractional resort, vacation\n                            ownership company, vacation club, or any hotel brand aﬃliated with a timeshare brand or\n                            a vacation club, or an\n                            agent, or a family member of an employee or an agent, of the promoter or any of its\n                            aﬃliates or vendors.\n                            Full-time students are not eligible. The Reservation partners &amp; Seller acts as\n                            independent agents for hotels\n                            and all other services supplied as part of this vacation package and shall not be liable\n                            for any loss,\n                            cancellation costs, delays, irregularities, accidents, injuries, damage to persons or\n                            property, indirect,\n                            incidental, special or consequential damages, arising from, or in conjunction with, any\n                            of these services. The\n                            Reservation partners &amp; Seller will not assume any responsibility and shall not be liable\n                            for delays,\n                            cancellations, or interruptions due to nature, strikes, Acts of God, acts of war or\n                            terrorism, and other acts\n                            beyond its control. This promotion will be offered throughout the U.S.; however, it is\n                            void where prohibited by\n                            law and where state regulation and/or licensing requirements have not been met.</span>\n                    </p>\n                    <p><br></p>\n                    <p><span>YOU MAY CANCEL THIS CONTRACT WITHOUT ANY PENALTY OR OBLIGATION WITHIN 30 DAYS FROM THE\n                            DATE OF PURCHASE. IF YOU\n                            DECIDE TO CANCEL, YOU MUST CONTACT THE SELLER; VacationGurus AT 855-344-8787, AVAILABE\n                            MONDAY &ndash; FRIDAY\n                            FROM 9:00 am &ndash; 5pm ET. NO PURCHASER SHALL RELY UPON REPRESENTATIONS OTHER THAN\n                            THOSE INCLUDED IN THIS\n                            CONTRACT. THIS CONTRACT IS FOR THE PURCHASE OF A DISCOUNTED VACATION OFFER AND PUTS ALL\n                            ASSIGNEES ON NOTICE OF\n                            THE CONSUMER&rsquo;S RIGHT TO CANCEL UNDER SECTION 559.933, FLORIDA STATUTES.</span></p>\n                    <p><br></p>\n                    <p><br></p>\n                    <p><span>To view the VacationGurus&nbsp;</span><span>Privacy Policy click below</span><span>&nbsp;</span>\n                    </p>\n                    <p><span>MANDATORY ARBITRATION/CLASS-ACTION WAIVER PROVISION:</span></p>\n                    <p><span>PLEASE READ THIS ARBITRATION PROVISION CAREFULLY TO UNDERSTAND YOUR</span></p>\n                    <p><span>RIGHTS. You have the right to opt out of this Agreement if you follow the instructions\n                            set out in the paragraph\n                            titled &ldquo;You Have the Right to Reject Arbitration or Opt Out of Arbitration&rdquo;\n                            below.</span></p>\n                    <p><br></p>\n                    <p><span>EXCEPT WHERE PROHIBITED BY LAW, IN THE EVENT OF A DISPUTE OR CLAIMS BETWEEN YOU AND\n                            Sunstate Client Services\n                            dba VacationGurus, A FLORIDA CORPORATION (HEREINAFTER &ldquo;US&rdquo;,\n                            &ldquo;OUR&rdquo;,\n                            &ldquo;VacationGurus&rdquo; OR &ldquo;WE&rdquo; AS APPROPRIATE) INCLUDING BUT NOT\n                            LIMITED TO ANY ARISING OUT OF\n                            OR RELATING TO (I) THIS ACCOUNT; (II) THE RELATIONSHIPS RESULTING FROM THIS ACCOUNT;\n                            (III) ANY ASPECT OF THE\n                            RELATIONSHIP BETWEEN YOU AND US; (IV) THE PRIVACY POLICY; (V) THE TERMS AND CONDITIONS;\n                            (VI) ANY TELEMARKETING\n                            OR OTHER CALL OR MESSAGE (INCLUDING BUT NOT LIMITED TO SMS//MMS/TEXT MESSAGES) YOU CLAIM\n                            TO HAVE RECEIVED FROM\n                            US OR ONE OF OUR PARTNERS; (VII) ANY E-MAIL YOU CLAIM TO HAVE RECEIVED FROM US OR ONE OF\n                            OUR PARTNERS; (VIII)\n                            YOUR USE OR ATTEMPTED USE OF ANY WEBSITE OF OURS OR OUR PARTNERS; OR (IX) ANY OFFERS OR\n                            PROMOTIONS; (X) ANY\n                            APPLICATIONS OR SUBMISSIONS OR (XI) OR ANY OTHER DISPUTE OR CLAIM BETWEEN YOU AND US (\n                            HEREINAFTER COLLECTIVELY\n                            KNOWN AS \"CLAIM\"), YOU AGREE THAT ANY CLAIM(S) YOU HAVE IN THE FUTURE MUST BE RESOLVED\n                            THROUGH FINAL\n                            AND BINDING CONFIDENTIAL ARBITRATION, AS DESCRIBED BELOW, INSTEAD OF IN COURT. ANY CLAIM\n                            (EXCEPT FOR A CLAIM\n                            CHALLENGING THE VALIDITY OR ENFORCEABILITY OF THIS ARBITRATION AGREEMENT, INCLUDING THE\n                            CLASS ACTION WAIVER)\n                            MUST BE RESOLVED THROUGH BINDING CONFIDENTIAL ARBITRATION. THIS MEANS NEITHER PARTY\n                            SHALL HAVE THE RIGHT TO\n                            LITIGATE SUCH CLAIM IN COURT OR TO HAVE A JURY TRIAL AND YOU VOLUNTARILY, AND KNOWINGLY\n                            ACKNOWLEDGE AND AGREE\n                            THAT YOU ARE WAIVING THE RIGHT TO A TRIAL BY JURY. YOU ALSO ACKNOWLEDGE AND AGREE THE\n                            RIGHTS THAT YOU WOULD HAVE\n                            IF YOU WENT TO COURT, SUCH AS DISCOVERY RIGHTS AND/OR THE RIGHT TO APPEAL ARE LIMITED IN\n                            ARBITRATION\n                            OR</span><span>&nbsp;</span><span>MAY NOT EXIST. This section applies regardless of\n                            whether such claims are\n                            based in contract, tort, statute, fraud, unfair competition, misrepresentation or any\n                            other legal theory.</span>\n                    </p>\n                    <p><br></p>\n                    <p><span>CLASS ACTION WAIVER: YOU AGREE THAT YOU ARE VOLUNTARILY AND KNOWINGLY AGREEING THAT\n                            ARBITRATION MUST BE ON AN\n                            INDIVIDUAL BASIS AND IN YOUR INDIVIDUAL CAPACITY AND NOT AS A PLAINTIFF (LEAD OR\n                            OTHERWISE) OR CLASS MEMBER IN\n                            ANY PURPORTED CLASS OR REPRESENTATIVE PROCEEDING(S). THIS MEANS NEITHER YOU NOR WE MAY\n                            JOIN OR CONSOLIDATE\n                            CLAIMS IN ARBITRATION BY OR AGAINST OTHER ACCOUNTHOLDERS, COMPANIES, INDIVIDUALS, ANY\n                            OTHER PURPORTED CLASS\n                            MEMBERS OR LITIGATE IN COURT OR ARBITRATE ANY CLAIMS AS A REPRESENTATIVE OR MEMBER OF A\n                            CLASS OR IN A PRIVATE\n                            ATTORNEY GENERAL CAPACITY. YOU FURTHER AGREE THAT THE ARBITRATOR MAY NOT CONSOLIDATE\n                            PROCEEDINGS OR CLAIMS OR\n                            OTHERWISE PRESIDE OVER ANY FORM OF A</span></p>\n                    <p><span>REPRESENTATIVE OR CLASS PROCEEDING. The arbitrator may award injunctive relief only in\n                            favor of the individual\n                            party seeking relief and only to the extent necessary to provide relief warranted by\n                            that party&rsquo;s\n                            individual claim. If a court decides that applicable law precludes enforcement of any of\n                            this paragraph&rsquo;s\n                            limitations as to a particular claim for relief, then after all appeals from that\n                            decision have been exhausted,\n                            that claim (and only that claim) must be severed from the arbitration and may be brought\n                            in court. Only a court,\n                            and not an arbitrator, shall determine the validity, scope, and effect of the Class\n                            Action\n                            Waiver.</span><span><br></span><span><br></span><span>Your Right to Go To Small Claims\n                            Court: You may choose to\n                            pursue your dispute or claim in small claims court (or your state&rsquo;s equivalent\n                            court) rather than by\n                            Arbitration if your dispute or Claim qualiﬁes for small claims court for the entirety of\n                            the proceeding. Such a\n                            small court dispute or Claim must be brought in a location where jurisdiction and venue\n                            over you and\n                            VacationGurus is proper. However, if such a dispute or Claim is transferred, removed or\n                            appealed to a different\n                            court, we may then demand/transfer the dispute or Claim to Arbitration pursuant to the\n                            terms of this Agreement.\n                            Additionally, any such small claims court claim shall be brought and maintained only as\n                            an individual action and\n                            shall not be joined or consolidated with any class or other representative\n                            action.</span></p>\n                    <p><br></p>\n                    <p><span>Any attempt to maintain a small claims court action as a non-individual action shall\n                            result in the immediate\n                            dismissal of the action, and you shall be liable to pay our reasonable attorney&rsquo;s\n                            fees and costs in\n                            connection with securing the dismissal of any such action.</span></p>\n                    <p><br></p>\n                    <p><span>Governing Law and Rules: This arbitration agreement is governed by the Federal\n                            Arbitration Act (FAA).\n                            Arbitration must proceed only with JAMS. The rules for the arbitration will be those in\n                            this arbitration\n                            agreement and the procedures of the chosen arbitration organization, but the rules in\n                            this arbitration agreement\n                            will be followed if there is disagreement between the agreement and the\n                            organization&rsquo;s procedures. If the\n                            organization&rsquo;s procedures change after the claim is ﬁled, the procedures in effect\n                            when the claim was ﬁled\n                            will apply.</span></p>\n                    <p><br></p>\n                    <p><span>Arbitration may be conducted through the submission of documents, by phone, or in\n                            person in the county where\n                            you live or at another mutually agreed location. The arbitrator shall follow the\n                            substantive laws of the State\n                            of Florida, excluding its conﬂict of law provisions unless we agree that the substantive\n                            law of the State in\n                            which you reside may be followed and applied. Any award rendered shall include a\n                            conﬁdential written opinion and\n                            shall be ﬁnal, subject to appeal under the FAA. Judgment on the award rendered by the\n                            arbitrator may be entered\n                            in any court of competent jurisdiction. For a copy of each organization&rsquo;s\n                            procedures, to ﬁle a claim or\n                            for other information, please contact:</span><span><br></span><span><br><br></span></p>\n                    <ul>\n                        <li>\n                            <p><span>JAMS at 620 Eighth Ave., Floor 34, New York, NY 10018,&nbsp;</span><span>www.jamsadr.com</span><span>&nbsp;</span><span>(phone\n                                    1-800-352-5267).</span></p>\n                        </li>\n                    </ul>\n                    <p><span>If JAMS is completely unavailable, and if you and we cannot agree on a substitute, then\n                            either you or we may\n                            request that a court with jurisdiction appoint a substitute arbitration\n                            company/arbitrator.</span></p>\n                    <p><br></p>\n                    <p><span>YOU AND WE AGREE NOT TO BRING OR PARTICIPATE IN A CLASS OR REPRESENTATIVE ACTION,\n                            PRIVATE ATTORNEY GENERAL\n                            ACTION OR COLLECTIVE ARBITRATION, EVEN IF PROCEDURES OR RULES WOULD OTHERWISE ALLOW ONE.\n                            THE ARBITRATOR MAY\n                            AWARD RELIEF ONLY IN FAVOR OF THE INDIVIDUAL PARTY SEEKING RELIEF AND ONLY TO THE EXTENT\n                            OF THAT PARTY&rsquo;S\n                            INDIVIDUAL CLAIM.</span></p>\n                    <p><br></p>\n                    <p><span>Fees and Costs: If you wish to begin arbitration against us but you cannot afford to\n                            pay the organizations or\n                            arbitrator&rsquo;s costs, we will advance those costs if you ask us in writing. Any\n                            request like this should be\n                            sent to Sunstate Client Services dba VacationGurus, Attn: Legal Department, 725 West SR\n                            434 Suite G, Longwood\n                            Fla 32750. If you lose the arbitration, the arbitrator will decide whether you must\n                            reimburse us for the money\n                            we advanced for you for the arbitration. If you win the arbitration, we will not ask for\n                            reimbursement of the\n                            money we advanced. Additionally, if you win the arbitration, the arbitrator may decide\n                            that you are entitled to\n                            be reimbursed for your reasonable attorneys&rsquo; fees and costs (if actually paid by\n                            you). The parties shall\n                            each pay their own additional fees, costs, and expenses, including, but not limited to,\n                            those for any attorneys,\n                            experts, documents, and witnesses.</span></p>\n                    <p><br></p>\n                    <p><span>Hearings and Decisions: Arbitration hearings will take place in the federal judicial\n                            district where you live. A\n                            single arbitrator will be appointed. The arbitrator must:</span></p>\n                    <p><br></p>\n                    <ul>\n                        <li>\n                            <p><span>Follow all applicable substantive law, except when contradicted by the\n                                    FAA;</span></p>\n                        </li>\n                        <li>\n                            <p><span>Follow applicable statutes of limitations.</span></p>\n                        </li>\n                        <li>\n                            <p><span>Honor valid claims of privilege.</span></p>\n                        </li>\n                        <li>\n                            <p><span>Issue a written decision including the reasons for the award.</span></p>\n                        </li>\n                    </ul>\n                    <p><br></p>\n                    <p><span>The arbitrator&rsquo;s decision will be ﬁnal and binding except for any review allowed\n                            by the FAA. However, if\n                            more than $100,000 was genuinely in dispute, then either you or we may choose to appeal\n                            to a new panel of three\n                            arbitrators. The appellate panel is completely free to accept or reject the entire\n                            original award or any part of\n                            it. The appeal must be ﬁled with the arbitration organization not later than 30 days\n                            after the original award is\n                            issued. The appealing party pays all appellate costs unless the appellate panel\n                            determines otherwise as part of\n                            its award.</span></p>\n                    <p><br></p>\n                    <p><span>Claim Notice and Special Payment: If you have a Claim, before initiating an arbitration\n                            proceeding, you may\n                            give us written notice of the Claim (\"Claim Notice\") at least 30 days before initiating\n                            the\n                            arbitration proceeding. The Claim Notice must include your name, address, phone number\n                            and account number (if\n                            applicable) and explain in reasonable detail the nature of the Claim and any supporting\n                            facts. Any Claim Notice\n                            shall be sent to us at Sunstate Client Services dba VacationGurus Attn: Legal\n                            Department, 725 West SR 434 Suite\n                            G, Longwood Fla 32750 (or such other address as we shall subsequently provide to you).\n                            If we provide you with a\n                            ﬁnal written settlement offer and you don&apos;t accept it, or we can&apos;t otherwise\n                            satisfactorily resolve\n                            your dispute, you must submit your dispute for resolution by arbitration as outlined\n                            above and in accordance\n                            with the arbitration organizations procedures. If, and only if, (1) you submit a Claim\n                            Notice in accordance with\n                            this Agreement on your own behalf (and not on behalf of any other party); and (2) an\n                            arbitrator, after ﬁnding in\n                            your favor in any respect on the merits of your claim, issues you an award that\n                            (excluding any arbitration fees\n                            or attorneys&rsquo; fees and costs awarded by the arbitrator) is greater than the value\n                            of VacationGurus&rsquo;s\n                            last written settlement offer made before an arbitrator was selected, then you will be\n                            entitled to the amount of\n                            the award or $5,000, whichever is greater. If you are entitled to the $5,000, you will\n                            receive in addition any\n                            arbitration fees or attorneys&rsquo; fees and costs awarded by the arbitrator. Any\n                            arbitration award may be\n                            enforced (such as through a judgment) in any court with\n                            jurisdiction.</span><span><br></span><span><br><br></span></p>\n                    <p><span>Other Beneﬁciaries of this Provision: In addition to you and us, the rights and duties\n                            described in this\n                            arbitration agreement apply to our Aﬃliates and our and their oﬃcers, directors and\n                            employees; any third-party\n                            co-defendant of a claim subject to this arbitration provision; and all joint Account\n                            Holders and Authorized\n                            Users of your Account(s) or relationship between us and you, including assignees. YOU\n                            AND WE AGREE NOT TO BRING\n                            OR PARTICIPATE IN A CLASS OR REPRESENTATIVE ACTION, PRIVATE ATTORNEY GENERAL ACTION OR\n                            COLLECTIVE ARBITRATION,\n                            EVEN IF FAA or JAMS PROCEDURES OR RULES WOULD OTHERWISE ALLOW ONE. THE ARBITRATOR MAY\n                            AWARD RELIEF ONLY IN FAVOR\n                            OF THE INDIVIDUAL PARTY SEEKING RELIEF AND ONLY TO THE EXTENT OF THAT PARTY&rsquo;S\n                            INDIVIDUAL CLAIM.</span></p>\n                    <p><br></p>\n                    <p><span>Survival of this Provision: This arbitration provision shall survive:</span></p>\n                    <p><br></p>\n                    <ul>\n                        <li>\n                            <p><span>closing of your Account;</span></p>\n                        </li>\n                        <li>\n                            <p><span>voluntary payment of your Account or any part of it;</span></p>\n                        </li>\n                        <li>\n                            <p><span>any legal proceedings to collect money you owe;</span></p>\n                        </li>\n                        <li>\n                            <p><span>any revocation of consent you provide to us;</span></p>\n                        </li>\n                        <li>\n                            <p><span>termination of any application or submission you provide to us;</span></p>\n                        </li>\n                        <li>\n                            <p><span>your use or attempted use of any websites of our or our partners;</span></p>\n                        </li>\n                        <li>\n                            <p><span>any bankruptcy by you; and</span></p>\n                        </li>\n                        <li>\n                            <p><span>any sale by us of your Account.</span></p>\n                        </li>\n                    </ul>\n                    <p><br></p>\n                    <p><span>You Have the Right to Reject Arbitration or Opt Out of Arbitration: You may reject the\n                            arbitration agreement\n                            and litigation &amp; class action waiver, but only if we receive from you a written notice\n                            of rejection within\n                            45 days of the following triggering events: (a) after your purchase is initiated; (b)\n                            you consent to the Privacy\n                            Policy or Terms and Conditions; (c) your use or attempted use of any of our or our\n                            partners websites; (d) your\n                            submission of an application (whether partial, incomplete, complete or otherwise) to us;\n                            (e) your submission or\n                            providing express written consent to us to receive e-mail(s), telephone call(s)\n                            (including SMS/MMS/Text\n                            Messages) or to receive any other information from us or our partners; or (f) signing up\n                            for or inquiring about\n                            an offer, deal or promotion from us (the 45 day time starts from whichever of the\n                            triggering events (a through\n                            f) comes ﬁrst in time). You must send the notice of rejection to: Sunstate Client\n                            Services dba VacationGurus,\n                            Attn: Legal Department, 725 West SR 434 Suite G, Longwood Fla 32750. Your rejection\n                            notice must include your\n                            name, address, phone number, Account number (if applicable), email address and personal\n                            signature. No one else\n                            may sign the rejection notice for you. Your rejection notice also must not be sent with\n                            any other\n                            correspondence. Rejection of arbitration will not affect your other rights or\n                            responsibilities under this\n                            Agreement. If you reject arbitration, neither you nor we will be subject to the\n                            arbitration provisions for this\n                            Account or any Claim or dispute between us and you. Rejection of arbitration for this\n                            Account, or any Claim or\n                            dispute between us and you, will not constitute rejection of any prior or future\n                            arbitration agreement between\n                            you and us. IF MORE THAN FORTY-FIVE (45) DAYS HAVE PASSED FROM THE EARLIEST TRIGGERING\n                            EVENT (listed in this\n                            paragraph under a through f above), YOU ARE NOT ELIGIBLE TO OPT OUT OF THIS PROVISION\n                            AND YOU MUST PURSUE YOUR\n                            CLAIM THROUGH BINDING ARBITRATION AS SET FORTH IN THIS AGREEMENT.</span></p>\n                </main>"
    },
    privacy: {
      title: "Privacy Policy",
      html: "<main class=\"legal-main\">\n                    <p><span>VacationGurus understands that privacy is important to you and wants your experience when dealing with us to be as enjoyable and safe as possible. This policy describes who Resort Save is and how it handles your personal information generally as well as when you use our website.</span></p>\n                    <p><br></p>\n                    <p><span>The type of personal information we collect and hold</span></p>\n                    <p><span>Personal information is information or an opinion about an identified individual or an individual who is reasonably identifiable. Depending on the products and service you ask us to provide, we may be required to collect some sensitive information when we are providing you with specialized services (such as access requirements for a disability).</span></p>\n                    <p><br></p>\n                    <p><span>We will ask for a broad range of personal information which is necessary for us to provide you with our services. The type of personal information we ask for will depend on which of the travel products with VacationGurus you book on and the type of product or service you choose.</span></p>\n                    <p><br></p>\n                    <p><span>We will generally ask for the following types of personal information</span></p>\n                    <ul>\n                        <li>\n                            <p><span>Name, address, email and contact details</span></p>\n                        </li>\n                        <li>\n                            <p><span>Date of birth</span></p>\n                        </li>\n                        <li>\n                            <p><span>Gender</span></p>\n                        </li>\n                        <li>\n                            <p><span>Information about your use of our product or service</span></p>\n                        </li>\n                    </ul>\n                    <p><span>Depending on the product or service you choose, you may also be asked other types of personal information such as:</span></p>\n                    <ul>\n                        <li>\n                            <p><span>Insurance-travel</span></p>\n                        </li>\n                        <li>\n                            <p><span>Identification</span></p>\n                        </li>\n                        <li>\n                            <p><span>Credit card details</span></p>\n                        </li>\n                    </ul>\n                    <p><br></p>\n                    <p><span>Ways we collect your personal information</span></p>\n                    <p><span>We collect your personal information:</span></p>\n                    <ul>\n                        <li>\n                            <p><span>By using written forms</span></p>\n                        </li>\n                        <li>\n                            <p><span>Through contact over the telephone, your mobile or other messaging technology</span></p>\n                        </li>\n                        <li>\n                            <p><span>Via the internet, including websites and social media</span></p>\n                        </li>\n                        <li>\n                            <p><span>In person to person contact</span></p>\n                        </li>\n                        <li>\n                            <p><span>Through subscription and entry forms</span></p>\n                        </li>\n                        <li>\n                            <p><span>Booking forms and requests for further information</span></p>\n                        </li>\n                        <li>\n                            <p><span>Emails, response devices</span></p>\n                        </li>\n                    </ul>\n                    <p><span>We will collect your personal information during the information life cycle, on an ad hoc or a recurrent basis using the above methods. For example, we will collect personal information when you acquire a product or service from us, when you make changes to that product, when you enquire on our product and services or request information on our services. We will combine or link personal information we already know about you to other personal information we collect about you.</span></p>\n                    <p><br></p>\n                    <p><span>We collect your personal information directly from you by written, by phone or through our online booking engine.</span></p>\n                    <p><br></p>\n                    <p><span>Please refer to &ldquo;Parties to whom we disclose and collect your personal information&rdquo; section which details the types of organizations we disclose your personal information to and collect your personal information from.</span></p>\n                    <p><br></p>\n                    <p><span>Cookies</span></p>\n                    <p><span>Our websites rely on &quot;cookies&quot; to provide a number of services to you. A cookie is a piece of data that a website sends to your browser and which is then stored on your computer or other internet enabled device. Cookies are generally one of two types, a session cookie or a persistent cookie. A session cookie is a temporary cookie that is placed on the device and remains until you leave one of our websites. A persistent cookie will remain on your device for a period of time or duration specified in the cookie despite you leaving our websites.</span></p>\n                    <p><br></p>\n                    <p><span>Cookies generally allow our websites you are browsing to interact more efficiently with your device. VacationGurus uses cookies to collect and use information for a range of purposes, including; to maintain and improve the operation of our websites; track user preferences and product requirements to customize our websites and target and improve advertising or marketing relevance. We may also have an arrangement with third parties who may use our cookies to improve the relevance of our advertising to you on third party websites. You are able to use your browser settings to manage cookies. These settings may include deleting all or some cookies, not accepting any cookies or being notified when cookies are being used.</span></p>\n                    <p><br></p>\n                    <p><span>Purposes of collection of personal information</span></p>\n                    <p><span>We collect your personal information so we can:</span></p>\n                    <ul>\n                        <li>\n                            <p><span>Identify you and provide you with our products and services including notifying you about new products, services and promotions from time to time</span></p>\n                        </li>\n                        <li>\n                            <p><span>Understand your requirements and provide you with a product or service</span></p>\n                        </li>\n                        <li>\n                            <p><span>Set up, administer and manage our products and services</span></p>\n                        </li>\n                    </ul>\n                    <p><span>Sometimes we are required to collect your personal information to satisfy specific legal obligations.</span></p>\n                    <p><br></p>\n                    <p><span>Use and disclosure</span></p>\n                    <p><span>We use and disclose your personal information for the purposes we collected it. For example, we will disclose your personal information to third party service providers so that they can provide the contracted services to VacationGurus such as information technology support or programming, hosting services, telephony services, mailing or sending of documentation to customers digitally or otherwise.</span></p>\n                    <p><br></p>\n                    <p><span>As a travel provider, VacationGurus offers products and services on behalf of a number of other providers including but not limited to cruise lines and insurance companies. VacationGurus maybe required to disclose your Personal Information to these providers to enable them to provide you with their services and to assist in making your experience a satisfying one. As these providers require this Personal Information when making your booking, if it is not provided we will not be able to finalize your booking.</span></p>\n                    <p><br></p>\n                    <p><span>There will be other instances when we may use and disclose your personal information including where: you have expressly or impliedly consented to the use or disclosure</span></p>\n                    <p><br></p>\n                    <p><span>Collection use and disclosure of personal information for marketing</span></p>\n                    <p><span>VacationGurus has a large range of travel services. Marketing is an important part of our business. We want to collect, use and disclose your personal information to keep you up to date with the range of products and services available from VacationGurus and which we think may be of interest to you. We use a wide variety of marketing strategies including mail, sms, telephone and other internet-based marketing including targeted online advertising and online behavioral marketing. Third party marketing service providers may combine the personal information we disclose to them with information they already hold about you, to serve you with more relevant advertising about our products and services.</span></p>\n                    <p><br></p>\n                    <p><span>We want you to be able to exercise your marketing preferences. Details of how to exercise your preferences can be made to our privacy officer whose contact details are below.</span></p>\n                    <p><br></p>\n                    <p><span>Parties to whom we disclose and collect your personal information</span></p>\n                    <p><span>As detailed in &ldquo;Ways we collect your personal information&rdquo; section there are a range of people and organizations (&lsquo;parties&rsquo;) to whom we disclose your personal information and collect personal information from &ndash; that are not you. These may be parties related to VacationGurus or third parties. The particular party will depend on which company or brand in VacationGurus you do business with and what product or service you receive.</span></p>\n                    <p><br></p>\n                    <p><span>Security of your personal information</span></p>\n                    <p><span>We hold your personal information in:</span></p>\n                    <ul>\n                        <li>\n                            <p><span>Computer systems</span></p>\n                        </li>\n                        <li>\n                            <p><span>Electronic databases</span></p>\n                        </li>\n                        <li>\n                            <p><span>Digital records</span></p>\n                        </li>\n                        <li>\n                            <p><span>Telephone recordings</span></p>\n                        </li>\n                        <li>\n                            <p><span>And in hard copy or paper files</span></p>\n                        </li>\n                    </ul>\n                    <p><span>We maintain industry standard technology and procedures in respect of our information management and provision of online services. VacationGurus has an ongoing program of review and enhancement of its security measures. The reviews and updates address such matters as security and information management policies, processes and procedures, and technology reviews such as software, virus protection and fire wall settings. VacationGurus systems and information technology infrastructure are regularly audited both by internal and external experts.</span></p>\n                    <p><br></p>\n                    <p><span>E-mail transmissions to Family Vacation Getaways, are not necessarily secure. If you have any concern about the security of the contents of your e-mail or any other transaction over the Internet, then you should consider contacting us by other means. VacationGurus does however employ HTTPS encryption techniques and the use of firewalls like financial institutions and internet transaction systems globally. If you make a transaction involving the submission of personal information over the Internet to VacationGurus using one of our online forms, then the VacationGurus employs that encryption technology. Once VacationGurus has received your personal information, it is stored and protected by a range of security controls, including firewalls, user identification requirements and audit trails.</span></p>\n                    <p><br></p>\n                    <p><span>VacationGurus trains its employees and representatives in their privacy obligations, applies confidentiality obligations and provides authorized persons with user identifiers, passwords or other access codes to control access to your personal information.</span></p>\n                    <p><br></p>\n                    <p><span>Non-customers</span></p>\n                    <p><span>You may not be a customer of ours, but you may interact with one of our companies. You may interact with one of our companies by using our transactional websites, entering a competition or commenting via social media. We will collect, use and disclose your personal information in accordance with this Privacy Policy and any Privacy Statement you may receive when you interact with us. Please see our Online Terms found on our transactional websites for more information about interacting with us via the Internet.</span></p>\n                    <p><br></p>\n                    <p><span>Vacation Gurus &ndash; Complaints Handling</span></p>\n                    <p><span>If you have a complaint about how we collect, hold, use or disclose your personal information or a privacy related issue such as refusal to provide access or correction, please use our complaints process so that we can help. It is important to follow the complaint handling process to resolve your complaint effectively and efficiently.</span></p>\n                    <p><br></p>\n                    <p><span>If you are subject to the Australian privacy regime, please note how we will deal with a complaint:</span></p>\n                    <p><br></p>\n                    <p><span>Step 1. Let us know</span></p>\n                    <p><span>If you would like to make a complaint, please let us know by contacting us. A response is usually provided to you within 5 business days by our privacy officer. You can contact us by using the relevant Complaints contact in the VacationGurus Privacy Contact Information below.</span></p>\n                    <p><br></p>\n                    <p><span>Step 2. Review by our Internal Privacy team</span></p>\n                    <p><span>If you are not satisfied with the outcome of the business review you can request the complaint, be referred to the Senior Management Team for review or you can contact them directly. Should additional information be required from you, we will contact you to discuss. The Senior Management Team will usually contact you with a decision within 25 business days of receiving your complaint. You can contact the Senior Management team by using the relevant contact in the VacationGurus Privacy Contact Information below.</span></p>\n                    <p><br></p>\n                    <p><span>Step 3. Seek review by an external service</span></p>\n                    <p><span>We expect our procedures will deal fairly and promptly with your complaint. However, if you remain dissatisfied, you may be able to access the services of an External Dispute Resolution Scheme such as the below.</span></p>\n                    <p><br></p>\n                    <p><span>VacationGurus</span></p>\n                    <p><br></p>\n                    <p><span>Changes and getting a copy of the Policy</span></p>\n                    <p><span>We encourage you to review and check our website regularly for any updates to this Privacy Policy. We will publish the updated version on this website and by continuing to deal with us, you accept this Privacy Policy as it applies from time to time. If you would like a copy of this Privacy Policy, please contact us. This policy was last updated on the 5th May 2018.</span></p>\n                </main>"
    }
  };

  var css = "" +
    ".legal-overlay{position:fixed;inset:0;z-index:1100;display:none;align-items:center;justify-content:center;padding:20px;background:rgba(16,34,47,.62);}" +
    ".legal-overlay.is-open{display:flex;}" +
    ".legal-overlay__card{position:relative;width:min(920px,96vw);height:min(760px,88vh);background:#fff;border-radius:14px;box-shadow:0 24px 64px rgba(0,0,0,.35);overflow:hidden;display:flex;flex-direction:column;}" +
    ".legal-overlay__bar{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:12px 16px;border-bottom:1px solid #e3e8ee;}" +
    ".legal-overlay__title{font-weight:800;font-size:16px;color:#10222f;margin:0;}" +
    ".legal-overlay__close{border:none;background:none;font-size:26px;line-height:1;cursor:pointer;color:#5b6b79;padding:2px 6px;}" +
    /* replaces the old iframe: the document body scrolls in-place */
    ".legal-overlay__body{flex:1;overflow-y:auto;-webkit-overflow-scrolling:touch;padding:0 16px;}" +
    ".legal-overlay .legal-main { max-width: 860px; margin: 0 auto; padding: 32px 20px 56px; }" +
    ".legal-overlay .legal-main h1 { font-size: 32px; font-weight: 800; color: var(--ink); margin: 0 0 6px; }" +
    ".legal-overlay .legal-updated { color: var(--muted); font-size: 14px; margin: 0 0 28px; }" +
    ".legal-overlay .legal-main h2 { font-size: 20px; font-weight: 800; color: var(--navy); margin: 28px 0 10px; }" +
    ".legal-overlay .legal-main p, .legal-overlay .legal-main li { font-size: 15px; line-height: 1.65; color: var(--text); }" +
    ".legal-overlay .legal-main ul { padding-left: 22px; }" +
    ".legal-overlay .legal-main a { color: var(--navy); }" +
    ".legal-overlay .legal-main { padding: 8px 4px 24px; }" +
    "@media (max-width:600px){.legal-overlay{padding:10px;}.legal-overlay__card{height:calc(100dvh - 20px);}.legal-overlay__body{padding:0 12px;}}";

  var EMPTY = {
    terms:
      '<p>Terms and Conditions have not been configured for this offer.</p></main>',
    privacy:
      '<main class="legal-main"><h1>Privacy Policy</h1>' +
      '<p>Privacy Policy has not been configured for this offer.</p></main>'
  };

  function wrapLegalHtml(html) {
    var t = String(html || "").trim();
    if (!t) return t;
    if (/class\s*=\s*["'][^"']*legal-main/i.test(t) || /<main[\s>]/i.test(t)) {
      return t;
    }
    return '<main class="legal-main">' + t + "</main>";
  }

  /**
   * Prefer offers.terms_conditions / privacy_policy injected on
   * window.SWIFTLY_OFFER_FLOW. When those keys are present (Offer Flow serve),
   * empty content shows EMPTY.* — not the hardcoded DOCS fallback.
   * Static front preview without offer_id keeps DOCS.
   */
  function resolveDoc(kind) {
    var meta = DOCS[kind];
    if (!meta) return null;
    var flow = window.SWIFTLY_OFFER_FLOW || {};
    var key = kind === "terms" ? "terms_conditions" : "privacy_policy";
    if (Object.prototype.hasOwnProperty.call(flow, key)) {
      var fromOffer = flow[key] == null ? "" : String(flow[key]).trim();
      return {
        title: meta.title,
        html: fromOffer ? wrapLegalHtml(fromOffer) : EMPTY[kind]
      };
    }
    return meta;
  }

  var style = document.createElement("style");
  style.textContent = css;
  document.head.appendChild(style);

  var overlay = document.createElement("div");
  overlay.className = "legal-overlay";
  overlay.setAttribute("aria-hidden", "true");
  overlay.innerHTML =
    '<div class="legal-overlay__card" role="dialog" aria-modal="true">' +
    '  <div class="legal-overlay__bar">' +
    '    <p class="legal-overlay__title"></p>' +
    '    <button type="button" class="legal-overlay__close" aria-label="Close">&times;</button>' +
    "  </div>" +
    '  <div class="legal-overlay__body"></div>' +
    "</div>";
  document.body.appendChild(overlay);

  var body = overlay.querySelector(".legal-overlay__body");
  var title = overlay.querySelector(".legal-overlay__title");
  var rendered = null;
  var renderedHtml = null;

  function open(kind) {
    var doc = resolveDoc(kind);
    if (!doc) return;
    title.textContent = doc.title;
    if (rendered !== kind || renderedHtml !== doc.html) {
      body.innerHTML = doc.html;
      body.querySelectorAll("[data-year]").forEach(function (el) {
        el.textContent = new Date().getFullYear();
      });
      rendered = kind;
      renderedHtml = doc.html;
    }
    body.scrollTop = 0;
    overlay.classList.add("is-open");
    overlay.setAttribute("aria-hidden", "false");
    document.body.style.overflow = "hidden";
  }
  function close() {
    overlay.classList.remove("is-open");
    overlay.setAttribute("aria-hidden", "true");
    document.body.style.overflow = "";
  }

  /* ---- Deep links: #terms / #privacy open the modal and stay in sync
     with the address bar, so the popup state is shareable and the
     back button dismisses it. ---- */
  var current = null; // kind currently shown: "terms" | "privacy" | null

  function kindFromHash() {
    var h = location.hash.replace("#", "");
    return h === "terms" || h === "privacy" ? h : null;
  }
  function syncFromHash() {
    var k = kindFromHash();
    if (k && k !== current) { current = k; open(k); }
    else if (!k && current) { current = null; close(); }
  }
  function requestClose() {
    // strip the hash without adding a history entry, then close
    if (kindFromHash()) history.replaceState(null, "", location.pathname + location.search);
    current = null;
    close();
  }

  window.addEventListener("hashchange", syncFromHash);
  syncFromHash(); // auto-open when the page is loaded with #terms / #privacy

  overlay.querySelector(".legal-overlay__close").addEventListener("click", requestClose);
  overlay.addEventListener("click", function (e) { if (e.target === overlay) requestClose(); });
  document.addEventListener("keydown", function (e) { if (e.key === "Escape" && overlay.classList.contains("is-open")) requestClose(); });

  // Keep full-page hrefs on the same Offer Flow host with current offer_id /
  // session_token so middle-click / Open in new tab still gets injected copy.
  function withOfferQuery(href) {
    try {
      var kind = legalKindFromHref(href);
      var u = new URL(kind === "privacy" ? "/checkout/pp" : "/checkout/tc", window.location.origin);
      var cur = new URLSearchParams(window.location.search || "");
      ["offer_id", "session_token"].forEach(function (k) {
        if (cur.get(k)) u.searchParams.set(k, cur.get(k));
      });
      try {
        var from = new URL(href, window.location.href);
        from.searchParams.forEach(function (v, k) {
          if (!u.searchParams.get(k)) u.searchParams.set(k, v);
        });
      } catch (e2) {}
      return u.pathname + (u.search ? u.search : "") + (u.hash || "");
    } catch (err) {
      return href;
    }
  }
  document.querySelectorAll('a[href*="terms-and-conditions"], a[href*="privacy-policy"], a[href*="/checkout/tc"], a[href*="/checkout/pp"], a[href="/checkout/tc"], a[href="/checkout/pp"]').forEach(function (a) {
    var href = a.getAttribute("href") || "";
    if (!isLegalHref(href)) return;
    a.setAttribute("href", withOfferQuery(href));
  });

  document.addEventListener("click", function (e) {
    var a = e.target.closest && e.target.closest("a[href]");
    if (!a || !isLegalHref(a.getAttribute("href") || "")) return;
    // Modifier / middle-click → full legal page (/checkout/tc|/pp) with offer query.
    // Normal left click (including links that had target=_blank) → in-page modal.
    if (e.metaKey || e.ctrlKey || e.shiftKey || e.altKey || e.button === 1) {
      return;
    }
    e.preventDefault();
    e.stopPropagation();
    location.hash = legalKindFromHref(a.getAttribute("href") || "") === "privacy" ? "privacy" : "terms";
  });
})();
